//! Drop-in replacement tests for `elicit_reqwest`.
//!
//! These tests verify that `elicit_reqwest` types work identically to their
//! reqwest counterparts at the call site. A `MockHttpClient` generated by
//! mockall proves that generic code written against [`HttpClient`] accepts
//! `elicit_reqwest::Client` without modification.

use elicit_reqwest::{Client, HttpClient, Method, RequestBuilder, Url};
use mockall::mock;
use mockall::predicate::eq;

mock! {
    /// Test double implementing the same [`HttpClient`] contract as the real client.
    pub TestClient {}

    impl HttpClient for TestClient {
        fn request_url(&self, method: Method, url: Url) -> RequestBuilder;
        fn get_url(&self, url: Url) -> RequestBuilder;
        fn post_url(&self, url: Url) -> RequestBuilder;
        fn put_url(&self, url: Url) -> RequestBuilder;
        fn delete_url(&self, url: Url) -> RequestBuilder;
        fn patch_url(&self, url: Url) -> RequestBuilder;
        fn head_url(&self, url: Url) -> RequestBuilder;
    }
}

fn example_url() -> Url {
    "https://example.com/api".parse().expect("valid URL")
}

fn real_builder_for(method: reqwest::Method, url: Url) -> RequestBuilder {
    Client::new().request_url(Method::from(method), url)
}

// ── Real client: verify method wiring ────────────────────────────────────────

#[test]
fn real_client_get_sets_get_method() {
    let url = example_url();
    let builder = Client::new().get_url(url.clone());
    let request = builder.build().expect("valid request");
    assert_eq!(request.method().as_str(), "GET");
    assert_eq!(request.url(), &url);
}

