// ── Mock client: verify trait is callable identically ────────────────────────

#[test]
fn mock_client_get_url_records_call() {
    let url = example_url();
    let mut mock = MockTestClient::new();
    mock.expect_get_url()
        .with(eq(url.clone()))
        .times(1)
        .returning(|u| real_builder_for(reqwest::Method::GET, u));

    let builder = mock.get_url(url.clone());
    let request = builder.build().expect("valid request");
    assert_eq!(request.method().as_str(), "GET");
    assert_eq!(request.url(), &url);
}

#[test]
fn mock_client_post_url_records_call() {
    let url = example_url();
    let mut mock = MockTestClient::new();
    mock.expect_post_url()
        .with(eq(url.clone()))
        .times(1)
        .returning(|u| real_builder_for(reqwest::Method::POST, u));

    let builder = mock.post_url(url.clone());
    let request = builder.build().expect("valid request");
    assert_eq!(request.method().as_str(), "POST");
}

#[test]
fn mock_client_request_url_accepts_custom_method() {
    let url = example_url();
    let method = Method::from(reqwest::Method::from_bytes(b"QUERY").expect("valid method"));
    let mut mock = MockTestClient::new();

    let method_clone = method.clone();
    mock.expect_request_url().times(1).returning(move |m, u| {
        real_builder_for(
            reqwest::Method::from_bytes(m.as_str().as_bytes()).expect("valid method"),
            u,
        )
    });

    let builder = mock.request_url(method_clone, url.clone());
    let request = builder.build().expect("valid request");
    assert_eq!(request.url(), &url);
}

// ── Drop-in: generic function works with both real and mock client ────────────

fn fetch_plan(client: &dyn HttpClient, url: Url) -> elicit_reqwest::Request {
    client.get_url(url).build().expect("valid request")
}

#[test]
fn generic_function_accepts_real_client() {
    let url = example_url();
    let client = Client::new();
    let request = fetch_plan(&client, url.clone());
    assert_eq!(request.method().as_str(), "GET");
    assert_eq!(request.url(), &url);
}

#[test]
fn generic_function_accepts_mock_client() {
    let url = example_url();
    let mut mock = MockTestClient::new();
    mock.expect_get_url()
        .times(1)
        .returning(|u| real_builder_for(reqwest::Method::GET, u));

    let request = fetch_plan(&mock, url.clone());
    assert_eq!(request.method().as_str(), "GET");
    assert_eq!(request.url(), &url);
}
